class Solution {
    struct Node {
        int next[2] = {-1, -1};
    };
    std::vector<Node> trie;
    void insert(long long val) {
        int curr = 0;
        for (int i = 48; i >= 0; --i) {
            int b = (val >> i) & 1;
            if (trie[curr].next[b] == -1) {
                trie[curr].next[b] = trie.size();
                trie.emplace_back();
            }
            curr = trie[curr].next[b];
        }
    }
    long long query(long long val) {
        int curr = 0;
        long long ans = 0;
        for (int i = 48; i >= 0; --i) {
            int b = (val >> i) & 1;
            int toggle = b ^ 1;
            if (trie[curr].next[toggle] != -1) {
                ans |= (1LL << i);
                curr = trie[curr].next[toggle];
            } else if (trie[curr].next[b] != -1) {
                curr = trie[curr].next[b];
            } else break;
        }
        return ans;
    }
