class Solution {
    static class TrieNode {
        TrieNode[] child = new TrieNode[2];
    }
    private TrieNode root = new TrieNode();
    private boolean hasInserted = false;
    private void insert(long val) {
        TrieNode curr = root;
        for (int i = 48; i >= 0; i--) {
            int b = (int)((val >> i) & 1);
            if (curr.child[b] == null) curr.child[b] = new TrieNode();
            curr = curr.child[b];
        }
    }
    private long query(long val) {
        TrieNode curr = root;
        long ans = 0;
        for (int i = 48; i >= 0; i--) {
            int b = (int)((val >> i) & 1);
            int toggle = b ^ 1;
            if (curr.child[toggle] != null) {
                ans |= (1L << i);
                curr = curr.child[toggle];
            } else if (curr.child[b] != null) {
                curr = curr.child[b];
            } else break;
        }
        return ans;
    }
    private long maxAns = 0;
    public long maxXor(int n, int[][] edges, int[] values) {
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        long[] subtreeSum = new long[n];
        getSums(0, -1, adj, values, subtreeSum);
        maxAns = 0;
        hasInserted = false;
        root = new TrieNode();
        dfs(0, -1, adj, subtreeSum);
        return maxAns;
    }
    private long getSums(int u, int p, java.util.List<Integer>[] adj, int[] values, long[] subtreeSum) {
        long s = values[u];
        for (int v : adj[u]) {
            if (v != p) s += getSums(v, u, adj, values, subtreeSum);
        }
        subtreeSum[u] = s;
        return s;
    }
    private void dfs(int u, int p, java.util.List<Integer>[] adj, long[] subtreeSum) {
        if (hasInserted) maxAns = Math.max(maxAns, query(subtreeSum[u]));
        for (int v : adj[u]) {
            if (v != p) dfs(v, u, adj, subtreeSum);
        }
        insert(subtreeSum[u]);
        hasInserted = true;
    }
}

var maxXor = function(n, edges, values) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const subtreeSum = new Array(n).fill(0n);
    const getSums = (u, p) => {
        let s = BigInt(values[u]);
        for (const v of adj[u]) {
            if (v !== p) s += getSums(v, u);
        }
        subtreeSum[u] = s;
        return s;
    };
    getSums(0, -1);
    const root = {};
    let hasInserted = false;
    const insert = (val) => {
        let curr = root;
        for (let i = 48n; i >= 0n; i--) {
            const b = Number((val >> i) & 1n);
            if (!curr[b]) curr[b] = {};
            curr = curr[b];
        }
    };
    const query = (val) => {
        let curr = root;
        let ans = 0n;
        for (let i = 48n; i >= 0n; i--) {
            const b = Number((val >> i) & 1n);
            const toggle = b ^ 1;
            if (curr[toggle]) {
                ans |= (1n << i);
                curr = curr[toggle];
            } else if (curr[b]) {
                curr = curr[b];
            } else break;
        }
        return ans;
    };
    let ans = 0n;
    const dfs = (u, p) => {
        if (hasInserted) {
            const candidate = query(subtreeSum[u]);
            if (candidate > ans) ans = candidate;
        }
        for (const v of adj[u]) {
            if (v !== p) dfs(v, u);
        }
        insert(subtreeSum[u]);
        hasInserted = true;
    };
    dfs(0, -1);
    return Number(ans);
};
